import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.DdtnLau3.js";const u=JSON.parse('{"title":"Core Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/index.md","filePath":"concepts/index.md"}'),n={name:"concepts/index.md"};function s(i,e,c,d,h,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h1><p>A Work is the unit you create, run, and share. Services give it concrete capabilities. The Harness understands the workspace and uses its tools and Services to perform tasks.</p><table tabindex="0"><thead><tr><th>Concept</th><th>A concrete example</th><th>What to read</th></tr></thead><tbody><tr><td>Work</td><td>A Kanban workspace with source files, board data, a running application, and conversation history.</td><td><a href="/piwork/concepts/work.html">Work</a></td></tr><tr><td>Service</td><td>The container running the board&#39;s web application and API.</td><td><a href="/piwork/concepts/service.html">Service</a></td></tr><tr><td>Harness</td><td>The layer that uses models and tools to build the board, inspect its state, and make changes.</td><td><a href="/piwork/concepts/harness.html">Harness</a></td></tr></tbody></table><h2 id="how-they-fit-together" tabindex="-1">How they fit together <a class="header-anchor" href="#how-they-fit-together" aria-label="Permalink to &quot;How they fit together&quot;">​</a></h2><p>The <strong>Work contains</strong> Services, data, tools, configuration, and its Harness. The <strong>Harness understands and operates</strong> those resources. <strong>Core manages</strong> the Work&#39;s lifecycle and Docker resources. <strong>Desktop / CLI</strong> gives you access to the Work.</p><p>The portable unit includes the runnable environment and its durable state. A conversation can explain a task; a Work also retains the files, Service definitions, fixed images, and context needed to continue it.</p><p>The <a href="/piwork/spec/">technical specifications</a> describe the current implementation and its boundaries.</p>',7)])])}const f=t(n,[["render",s]]);export{u as __pageData,f as default};
